<template><div class="prize-page"><el-card shadow="never" class="!border-none"><el-form :model="filters" inline><el-form-item label="奖项名称"><el-input v-model="filters.keyword" clearable placeholder="请输入奖项名称" /></el-form-item><el-form-item label="奖项状态"><el-select v-model="filters.status" clearable placeholder="全部状态"><el-option label="启用" value="启用" /><el-option label="禁用" value="禁用" /></el-select></el-form-item><el-form-item><el-button type="primary" @click="resetPage">查询</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form></el-card><el-card shadow="never" class="!border-none mt-4"><template #header><div class="heading"><span class="card-title">奖项列表</span><el-button type="primary" :icon="Plus" @click="openForm()">添加奖项</el-button></div></template><el-table :data="paged" stripe table-layout="fixed" class="prize-table"><el-table-column label="ID" prop="id" min-width="160" class-name="first-column" label-class-name="first-column" /><el-table-column label="奖项名称" prop="name" min-width="220" /><el-table-column label="奖项状态" min-width="180"><template #default="{row}"><el-switch v-model="row.enabled" @change="notifyStatus(row)" /></template></el-table-column><el-table-column label="排序" prop="sort" min-width="180" /><el-table-column label="操作" min-width="180" class-name="last-column" label-class-name="last-column"><template #default="{row}"><el-button link type="primary" @click="openForm(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><div class="flex justify-end mt-4"><el-pagination v-model:current-page="page" background layout="total, prev, pager, next" :total="filtered.length" /></div></el-card><el-dialog v-model="visible" :title="editing ? '编辑奖项' : '添加奖项'" width="440px"><el-form :model="form" label-width="86px"><el-form-item label="奖项名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="奖项状态"><el-radio-group v-model="form.enabled"><el-radio :value="true">启用</el-radio><el-radio :value="false">禁用</el-radio></el-radio-group></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sort" :min="0" /></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">确定</el-button></template></el-dialog></div></template>
<script lang="ts" setup name="batchPrizes">
import { Plus } from '@element-plus/icons-vue'
import { ElMessageBox } from 'element-plus'
interface Prize { id: string; name: string; enabled: boolean; sort: number; linkedCodes: number }
const prizes = reactive<Prize[]>([{ id: 'PR1001', name: '一等奖', enabled: true, sort: 100, linkedCodes: 12 }, { id: 'PR1002', name: '二等奖', enabled: true, sort: 90, linkedCodes: 48 }, { id: 'PR1003', name: '三等奖', enabled: true, sort: 80, linkedCodes: 120 }, { id: 'PR1004', name: '谢谢参与', enabled: false, sort: 10, linkedCodes: 0 }]); const filters = reactive({ keyword: '', status: '' }); const page = ref(1); const pageSize = 10; const visible = ref(false); const editing = ref(''); const form = reactive({ name: '', enabled: true, sort: 0 }); const filtered = computed(() => prizes.filter(p => (!filters.keyword || p.name.includes(filters.keyword.trim())) && (!filters.status || (filters.status === '启用') === p.enabled))); const paged = computed(() => filtered.value.slice((page.value - 1) * pageSize, page.value * pageSize)); const resetPage = () => { page.value = 1 }; const reset = () => { filters.keyword = ''; filters.status = ''; resetPage() }; const notifyStatus = (p: Prize) => ElMessage.success(`奖项已${p.enabled ? '启用' : '禁用'}`); const openForm = (p?: Prize) => { editing.value = p?.id || ''; Object.assign(form, p ? { name: p.name, enabled: p.enabled, sort: p.sort } : { name: '', enabled: true, sort: 0 }); visible.value = true }; const save = () => { if (!form.name.trim()) return ElMessage.error('请输入奖项名称'); if (editing.value) { const p = prizes.find(x => x.id === editing.value); if (p) Object.assign(p, form) } else prizes.unshift({ ...form, id: `PR${Date.now()}`, linkedCodes: 0 }); visible.value = false; ElMessage.success('奖项已保存') }; const remove = async (p: Prize) => { if (p.linkedCodes) return ElMessage.warning('该奖项已有关联奖码数据，暂不可删除'); try { await ElMessageBox.confirm(`确定删除奖项“${p.name}”吗？`, '删除奖项', { type: 'warning' }); prizes.splice(prizes.indexOf(p), 1); ElMessage.success('奖项已删除') } catch {} }
</script>
<style scoped lang="scss">.heading{display:flex;align-items:center;justify-content:space-between}.prize-table :deep(.first-column .cell){padding-left:16px}.prize-table :deep(.last-column .cell){padding-right:16px}</style>
